import unittest

from solucao import juntar


class TestJuntarNumaString(unittest.TestCase):
    def test_junta_com_virgula(self):
        """juntar devolve os itens colados com a virgula"""
        self.assertEqual(juntar(",", ["uva", "pera"]), "uva,pera")

    def test_junta_numeros_convertendo_para_texto(self):
        """juntar converte os numeros para texto antes de colar"""
        self.assertEqual(juntar("-", [1, 2, 3]), "1-2-3")

    def test_separador_vazio_cola_tudo(self):
        """juntar cola os itens sem nada entre eles quando o separador e vazio"""
        self.assertEqual(juntar("", ["a", "b"]), "ab")

    def test_lista_vazia_devolve_vazio(self):
        """juntar devolve o texto vazio para a lista vazia"""
        self.assertEqual(juntar("-", []), "")

